<script setup>
import {Head} from '@inertiajs/vue3';import AdminLayout from '../../../Layouts/AdminLayout.vue';import DataPanel from '../../../Components/Ui/DataPanel.vue';import EmptyState from '../../../Components/Ui/EmptyState.vue';import PageHeader from '../../../Components/Ui/PageHeader.vue';import StatRail from '../../../Components/Ui/StatRail.vue';
defineOptions({layout:AdminLayout});defineProps({ingredient:{type:Object,required:true},stats:{type:Object,required:true},supplierCards:{type:Array,default:()=>[]},history:{type:Array,default:()=>[]},urls:{type:Object,required:true}});
</script>
<template><Head :title="`تاريخ سعر ${ingredient.name}`"/><PageHeader :title="`تاريخ سعر ${ingredient.name}`" icon="bi-graph-up-arrow" :subtitle="`كل سعر استلام محوّل إلى الوحدة الأساسية (${ingredient.unit})`" :crumbs="[{label:'المكونات',url:urls.ingredients}]"><template #actions><a :href="urls.compare" class="btn btn-primary"><i class="bi bi-arrows-collapse"></i> مقارنة الموردين</a></template></PageHeader><StatRail :stats="[{label:'آخر سعر',value:stats.latest,icon:'bi-tag-fill',color:'primary'},{label:'أدنى سعر',value:stats.min,icon:'bi-arrow-down-circle-fill',color:'success'},{label:'أعلى سعر',value:stats.max,icon:'bi-arrow-up-circle-fill',color:'danger'},{label:'الموردون',value:stats.suppliers,icon:'bi-truck',color:'accent'}]"/><div v-if="supplierCards.length" class="price-cards"><article v-for="card in supplierCards" :key="card.id??card.name"><div><strong>{{card.name}}</strong><small>{{card.count}} عملية استلام</small></div><span :class="`is-${card.changeColor}`">{{card.changeLabel}}</span><b>{{card.latest}} <small>/ {{ingredient.unit}}</small></b><time>{{card.updatedAgo}}</time></article></div><DataPanel title="سجل الأسعار" :count="history.length" icon="bi-clock-history"><div v-if="history.length" class="history"><article v-for="row in history" :key="row.id"><time><b>{{row.date}}</b><small>{{row.ago}}</small></time><strong>{{row.supplier}}</strong><span><small>السعر المدفوع</small><b>{{row.paidPrice}}</b></span><span><small>للوحدة الأساسية</small><b class="green">{{row.basePrice}}</b></span><em :class="`is-${row.changeColor}`">{{row.changeLabel}}</em><a v-if="row.sourceUrl" :href="row.sourceUrl">{{row.source}}</a><b v-else class="source">{{row.source}}</b><small>{{row.recordedBy}}</small></article></div><EmptyState v-else icon="bi-graph-up" title="لا يوجد سجل أسعار" message="يبدأ التسجيل تلقائياً مع أول استلام أمر شراء."/></DataPanel></template>
<style scoped>.price-cards{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-bottom:10px}.price-cards article{display:grid;grid-template-columns:1fr auto;gap:6px;padding:13px;border:1px solid #e1e8e3;border-radius:13px;background:#fff}.price-cards article>div{display:grid}.price-cards strong{font-size:.69rem}.price-cards small,.history small{color:#829087;font-size:.55rem}.price-cards span,.history em{padding:3px 6px;border-radius:99px;font-size:.54rem;font-style:normal;font-weight:800}.price-cards article>b{grid-column:1/-1;color:#176b39;font-size:.87rem}.price-cards time{grid-column:1/-1;color:#829087;font-size:.55rem}.is-success{color:#176b39;background:#e7f5eb}.is-danger{color:#b42318;background:#feecec}.is-warning{color:#955900;background:#fff0d2}.is-secondary{color:#68776e;background:#edf0ee}.history{display:grid;gap:6px}.history article{display:grid;grid-template-columns:125px minmax(120px,1fr) repeat(2,minmax(120px,.8fr)) auto minmax(100px,.7fr) 90px;align-items:center;gap:8px;padding:10px;border:1px solid #e1e8e3;border-radius:11px}.history time,.history span{display:grid}.history time b,.history strong,.history span b{font-size:.62rem}.history .green{color:#176b39}.history a{color:#176b39;font-size:.58rem;font-weight:800}.history .source{font-size:.56rem}@media(max-width:900px){.price-cards{grid-template-columns:1fr 1fr}.history article{grid-template-columns:100px 1fr 1fr}.history article>*:nth-child(n+4){display:none}}@media(max-width:550px){.price-cards{grid-template-columns:1fr}.history article{grid-template-columns:1fr 1fr}.history article>time{grid-column:1/-1}}</style>
